"use client";
import { useState } from "react";

// Assumes 'use client' keeps this out of the server render
export function ThemeToggle() {
  const [theme, setTheme] = useState(
    () => window.localStorage.getItem("theme") ?? "light",
  ); // SSR: ReferenceError: window is not defined
  const next = theme === "dark" ? "light" : "dark";
  return <button onClick={() => setTheme(next)}>Theme: {theme}</button>;
}

"use client";
import { Suspense, use, useState } from "react";
import { browser } from "react-dom";

function SavedTheme() {
  use(browser("The theme lives in localStorage")); // server: fallback
  const [theme, setTheme] = useState(
    () => window.localStorage.getItem("theme") ?? "light",
  );
  const next = theme === "dark" ? "light" : "dark";
  return <button onClick={() => setTheme(next)}>Theme: {theme}</button>;
}

export function ThemeToggle() {
  return (
    <Suspense fallback={<button disabled>Theme</button>}>
      <SavedTheme />
    </Suspense>
  );
}
